using System;using System.Linq;using Newtonsoft.Json.Linq;
namespace SpatialWallpaper.Sdk.Native {
 public static class NativeResourceRules {
  public static void Check(JArray args){JsonData.Require(args!=null&&args.Count==5&&args[0].Type==JTokenType.Integer&&(long)args[0]>0,"native-resource-envelope");JsonData.Integer(args[1],1,int.MaxValue);string action=JsonData.Text(args[2],32);JsonData.Require(SceneCommandRules.Id(args[3])>0,"native-resource-target");var payload=args[4] as JArray;JsonData.Require(payload!=null,"native-resource-payload");switch(action){case "begin_mesh":JsonData.Require(payload.Count==2,"native-resource-mesh");var counts=JsonData.Array(payload[1],64).Select(c=>JsonData.Integer(c,3,196608)).ToArray();NativeUploadSpec.Mesh(JsonData.Integer(payload[0],3,8192),counts);break;case "begin_texture":JsonData.Require(payload.Count==3,"native-resource-texture");JsonData.Text(payload[0],128);NativeUploadSpec.Texture(JsonData.Integer(payload[1],1,512),JsonData.Integer(payload[2],1,512));break;case "chunk":JsonData.Require(payload.Count==2,"native-resource-chunk");JsonData.Integer(payload[0],0,1048576);string encoded=JsonData.Text(payload[1],21848);byte[] bytes=Convert.FromBase64String(encoded);JsonData.Require(bytes.Length>0&&bytes.Length<=16384&&Convert.ToBase64String(bytes)==encoded,"native-resource-chunk-size-or-encoding");break;case "seal":case "poll":case "apply":case "cancel":case "release":JsonData.Require(payload.Count==0,"native-resource-no-payload");break;default:throw new System.IO.InvalidDataException("native-resource-action");}}
 }
}
